# Layout (all integers in the framing headers are unsigned big-endian):
#
#   magic (4) || version (1) || proof_type (1)
#   frame(x_commitment) || frame(y_commitment) || frame(region)
#   frame(context) || frame(proof)
#
# frame(x) = uint32be(len(body)) || body. Integers use a sign-prefixed
# shortest big-endian body (1 = non-negative, 255 = negative, then the
# shortest big-endian magnitude, so zero encodes as 01 00). Structured
# bodies carry an explicit tuple cardinality; the one-byte proof-type tag
# in the header makes RegionProof and RegionWideProof byte-distinguishable,
# and the proof body is always the two axis sub-proofs in (x, y) order.

_BUNDLE_MAGIC = b"zrgn"
_BUNDLE_VERSION = 1
_BUNDLE_PROOF_TYPE_REGION = 1
_BUNDLE_PROOF_TYPE_REGION_WIDE = 2
_INT_SIGN_POSITIVE = 1
_INT_SIGN_NEGATIVE = 255


@dataclass(frozen=True)
class RegionProofBundle:
    """A versioned, canonical binary envelope for one region proof.

    Fields, in the fixed wire order: ``x_commitment`` / ``y_commitment``
    (:class:`PedersenCommitment`), ``region`` (:class:`Region`),
    ``context`` (``bytes``) and ``proof`` (a :class:`RegionProof` or
    :class:`RegionWideProof`). Bundles are positional construction
    arguments, compare by value and are immutable; construction performs no
    validation — use :func:`encode_region_proof_bundle` /
    :func:`verify_region_proof_bundle` to check.
    """

    x_commitment: PedersenCommitment
    y_commitment: PedersenCommitment
    region: Region
    context: bytes
    proof: RegionProof | RegionWideProof


def _bundle_frame(body: bytes) -> bytes:
    """One length-prefixed envelope item: four-byte big-endian length plus body."""
    return len(body).to_bytes(4, "big") + body


def _bundle_int(value: int) -> bytes:
    """Canonical signed arbitrary-precision integer body (no length frame)."""
    sign = _INT_SIGN_POSITIVE if value >= 0 else _INT_SIGN_NEGATIVE
    magnitude = abs(value)
    return bytes((sign,)) + magnitude.to_bytes(
        max(1, (magnitude.bit_length() + 7) // 8), "big"
    )


def _bundle_tuple(items: Sequence[bytes]) -> bytes:
    """A tuple body: four-byte cardinality followed by the framed items."""
    body = len(items).to_bytes(4, "big")
    for item in items:
        body += _bundle_frame(item)
    return body


def _bundle_commitment(commitment: PedersenCommitment) -> bytes:
    """A PedersenCommitment body: its six integer fields, in field order."""
    return _bundle_tuple(
        [
            _bundle_int(getattr(commitment, name))
            for name in ("element", "lower", "upper", "prime", "generator", "h")
        ]
    )


def _bundle_region(region: Region) -> bytes:
    """A Region body: its four bounds in field order (min_x, max_x, min_y, max_y)."""
    return _bundle_tuple(
        [
            _bundle_int(getattr(region, name))
            for name in ("min_x", "max_x", "min_y", "max_y")
        ]
    )


def _bundle_range_proof(proof: RangeProof) -> bytes:
    """A RangeProof body: three integer tuples ``(t, e, s)``, in field order."""
    return _bundle_tuple(
        [
            _bundle_tuple([_bundle_int(item) for item in proof.t]),
            _bundle_tuple([_bundle_int(item) for item in proof.e]),
            _bundle_tuple([_bundle_int(item) for item in proof.s]),
        ]
    )


def _bundle_wide_range_proof(proof: WideRangeProof) -> bytes:
    """A WideRangeProof body: commitments plus challenge/response integer pairs."""
    return _bundle_tuple(
        [
            _bundle_tuple([_bundle_int(item) for item in proof.commitments]),
            _bundle_tuple(
                [
                    _bundle_tuple([_bundle_int(pair[0]), _bundle_int(pair[1])])
                    for pair in proof.challenges
                ]
            ),
            _bundle_tuple(
                [
                    _bundle_tuple([_bundle_int(pair[0]), _bundle_int(pair[1])])
                    for pair in proof.responses
                ]
            ),
        ]
    )


def _bundle_proof(proof: RegionProof | RegionWideProof) -> tuple[int, bytes]:
    """Return ``(proof_type_tag, proof body)`` for the bundle payload.

    The proof body is a two-item tuple (the x then the y axis sub-proof);
    the type tag lives in the envelope header next to the format version.
    """
    if isinstance(proof, RegionProof):
        body = _bundle_tuple(
            [
                _bundle_range_proof(proof.x_proof),
                _bundle_range_proof(proof.y_proof),
            ]
        )
        return _BUNDLE_PROOF_TYPE_REGION, body
    body = _bundle_tuple(
        [
            _bundle_wide_range_proof(proof.x_proof),
            _bundle_wide_range_proof(proof.y_proof),
        ]
    )
    return _BUNDLE_PROOF_TYPE_REGION_WIDE, body


def _bundle_check_int(value: object, name: str) -> None:
    """Bundle integers are non-bool ints, like the rest of the public API."""
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError(f"{name} must be an integer")


def _bundle_check_commitment(commitment: object, name: str) -> None:
    if not isinstance(commitment, PedersenCommitment):
        raise TypeError(f"{name} must be a PedersenCommitment")
    for field_name in ("element", "lower", "upper", "prime", "generator", "h"):
        _bundle_check_int(getattr(commitment, field_name), f"{name} {field_name}")


def _bundle_check_region(region: object, *, enforce_order: bool) -> None:
    if not isinstance(region, Region):
        raise TypeError("region must be a Region")
    for field_name in ("min_x", "max_x", "min_y", "max_y"):
        _bundle_check_int(getattr(region, field_name), f"region {field_name}")
    if enforce_order and (
        region.min_x > region.max_x or region.min_y > region.max_y
    ):
        raise ValueError("region bounds must satisfy min <= max on each axis")


def _bundle_check_range_proof(proof: object, name: str) -> None:
    if not isinstance(proof, RangeProof):
        raise TypeError(f"{name} must be a RangeProof")
    for field_name in ("t", "e", "s"):
        field = getattr(proof, field_name)
        if not isinstance(field, tuple):
            raise TypeError(f"{name} {field_name} must be a tuple of integers")
        for position, item in enumerate(field):
            _bundle_check_int(item, f"{name} {field_name}[{position}]")


def _bundle_check_wide_range_proof(proof: object, name: str) -> None:
    if not isinstance(proof, WideRangeProof):
        raise TypeError(f"{name} must be a WideRangeProof")
    if not isinstance(proof.commitments, tuple):
        raise TypeError(f"{name} commitments must be a tuple of integers")
    for position, item in enumerate(proof.commitments):
        _bundle_check_int(item, f"{name} commitments[{position}]")
    for field_name in ("challenges", "responses"):
        field = getattr(proof, field_name)
        if not isinstance(field, tuple):
            raise TypeError(f"{name} {field_name} must be a tuple of integer pairs")
        for index, pair in enumerate(field):
            if not isinstance(pair, tuple):
                raise TypeError(
                    f"{name} {field_name} must be a tuple of integer pairs"
                )
            if len(pair) != 2:
                raise TypeError(
                    f"{name} {field_name}[{index}] must be an integer pair"
                )
            _bundle_check_int(pair[0], f"{name} {field_name}[{index}][0]")
            _bundle_check_int(pair[1], f"{name} {field_name}[{index}][1]")


def encode_region_proof_bundle(bundle: RegionProofBundle) -> bytes:
    """Encode a :class:`RegionProofBundle` into its canonical byte envelope.

    The same bundle object always encodes to the same byte string. The
    output starts with the four-byte magic ``b"zrgn"``, a one-byte format
    version and a one-byte proof-type tag, followed by the five fields in
    fixed order (``x_commitment``, ``y_commitment``, ``region``,
    ``context``, ``proof``); each item is length-prefixed with a four-byte
    big-endian header. Arbitrary-precision integers (including negative
    bounds) carry a sign byte and a shortest big-endian magnitude; tuples
    carry an explicit cardinality. The function returns ``bytes`` only and
    never writes to the file system or a database.

    A wrong object or field type (including a ``bool`` integer, a
    non-tuple proof field, a wide-proof pair that is not a two-tuple, or a
    proof that is neither a :class:`RegionProof` nor a
    :class:`RegionWideProof`) raises :class:`TypeError`. A region with
    ``min > max`` on an axis cannot be built through the public
    :class:`Region` constructor; if such an object is forged bypassing the
    constructor, it is rejected with :class:`ValueError`.
    """
    if not isinstance(bundle, RegionProofBundle):
        raise TypeError("bundle must be a RegionProofBundle")
    _bundle_check_commitment(bundle.x_commitment, "x_commitment")
    _bundle_check_commitment(bundle.y_commitment, "y_commitment")
    _bundle_check_region(bundle.region, enforce_order=True)
    if not isinstance(bundle.context, bytes):
        raise TypeError("context must be bytes")
    proof = bundle.proof
    if isinstance(proof, RegionProof):
        _bundle_check_range_proof(proof.x_proof, "proof x_proof")
        _bundle_check_range_proof(proof.y_proof, "proof y_proof")
    elif isinstance(proof, RegionWideProof):
        _bundle_check_wide_range_proof(proof.x_proof, "proof x_proof")
        _bundle_check_wide_range_proof(proof.y_proof, "proof y_proof")
    else:
        raise TypeError("proof must be a RegionProof or RegionWideProof")
    proof_type, proof_body = _bundle_proof(proof)
    out = bytearray()
    out += _BUNDLE_MAGIC
    out += bytes((_BUNDLE_VERSION, proof_type))
    out += _bundle_frame(_bundle_commitment(bundle.x_commitment))
    out += _bundle_frame(_bundle_commitment(bundle.y_commitment))
    out += _bundle_frame(_bundle_region(bundle.region))
    out += _bundle_frame(bundle.context)
    out += _bundle_frame(proof_body)
    return bytes(out)


class _BundleReader:
    """Cursor over the envelope payload with strict bounds checking.

    Every read validates its length prefix and element type before
    returning; any truncation, overflow, cardinality or tag mismatch raises
    :class:`ValueError`. The whole envelope must be consumed exactly.
    """

    def __init__(self, data: bytes) -> None:
        self._data = data
        self._offset = 0

    def take(self, size: int) -> bytes:
        if size < 0 or self._offset + size > len(self._data):
            raise ValueError("truncated region proof bundle payload")
        chunk = self._data[self._offset : self._offset + size]
        self._offset += size
        return chunk

    def byte(self, what: str) -> int:
        return self.take(1)[0]

    def expect(self, expected: bytes, what: str) -> None:
        actual = self.take(len(expected))
        if actual != expected:
            raise ValueError(f"invalid {what}")

    def uint32(self) -> int:
        return int.from_bytes(self.take(4), "big")

    def frame(self, what: str) -> bytes:
        length = self.uint32()
        return self.take(length)

    def at_end(self) -> bool:
        return self._offset == len(self._data)

    def int_value(self, what: str) -> int:
        body = self.frame(what)
        if len(body) < 2:
            raise ValueError(f"{what} integer is too short")
        sign = body[0]
        if sign not in (_INT_SIGN_POSITIVE, _INT_SIGN_NEGATIVE):
            raise ValueError(f"{what} integer has an unknown sign byte")
        magnitude = int.from_bytes(body[1:], "big")
        # Canonical shortest form: no leading zero magnitude bytes and no
        # negative zero.
        if body[1] == 0 and len(body) > 2:
            raise ValueError(f"{what} integer is not in canonical form")
        if sign == _INT_SIGN_NEGATIVE and magnitude == 0:
            raise ValueError(f"{what} integer uses a non-canonical negative zero")
        return -magnitude if sign == _INT_SIGN_NEGATIVE else magnitude

    def tuple_cardinality(self, what: str) -> int:
        return int.from_bytes(self.take(4), "big")

    def integer_tuple(self, what: str) -> tuple[int, ...]:
        body = self.frame(what)
        inner = _BundleReader(body)
        count = inner.tuple_cardinality(what)
        items = [inner.int_value(f"{what}[{i}]") for i in range(count)]
        if not inner.at_end():
            raise ValueError(f"{what} tuple has trailing data")
        return tuple(items)

    def commitment(self, what: str) -> PedersenCommitment:
        body = self.frame(what)
        inner = _BundleReader(body)
        count = inner.tuple_cardinality(what)
        if count != 6:
            raise ValueError(f"{what} commitment must have exactly six fields")
        values = [
            inner.int_value(f"{what} {name}")
            for name in ("element", "lower", "upper", "prime", "generator", "h")
        ]
        if not inner.at_end():
            raise ValueError(f"{what} commitment has trailing data")
        element, lower, upper, prime, generator, h = values
        if prime <= 3:
            raise ValueError(f"{what} prime must be greater than 3")
        if not 1 < generator < prime:
            raise ValueError(f"{what} generator must satisfy 1 < generator < prime")
        if not 1 < h < prime:
            raise ValueError(f"{what} h must satisfy 1 < h < prime")
        if not 0 < element < prime:
            raise ValueError(f"{what} element must satisfy 0 < element < prime")
        if lower > upper:
            raise ValueError(f"{what} lower must not exceed upper")
        if upper - lower >= prime - 1:
            raise ValueError(f"{what} range width must be smaller than prime - 1")
        return PedersenCommitment(*values)

    def region(self) -> Region:
        body = self.frame("region")
        inner = _BundleReader(body)
        count = inner.tuple_cardinality("region")
        if count != 4:
            raise ValueError("region must have exactly four bounds")
        min_x, max_x, min_y, max_y = (
            inner.int_value(f"region {name}")
            for name in ("min_x", "max_x", "min_y", "max_y")
        )
        if not inner.at_end():
            raise ValueError("region has trailing data")
        return Region(min_x=min_x, max_x=max_x, min_y=min_y, max_y=max_y)

    def range_proof(self, what: str) -> RangeProof:
        body = self.frame(what)
        inner = _BundleReader(body)
        count = inner.tuple_cardinality(what)
        if count != 3:
            raise ValueError(f"{what} range proof must have exactly three fields")
        t = inner.integer_tuple(f"{what} t")
        e = inner.integer_tuple(f"{what} e")
        s = inner.integer_tuple(f"{what} s")
        if not inner.at_end():
            raise ValueError(f"{what} range proof has trailing data")
        size = len(t)
        if not (1 <= size <= _MAX_RANGE_VALUES) or not (
            len(e) == size and len(s) == size
        ):
            raise ValueError(
                f"{what} range proof fields must be equal-length tuples of "
                f"1..{_MAX_RANGE_VALUES} integers"
            )
        return RangeProof(t=t, e=e, s=s)

    def wide_range_proof(self, what: str) -> WideRangeProof:
        body = self.frame(what)
        inner = _BundleReader(body)
        count = inner.tuple_cardinality(what)
        if count != 3:
            raise ValueError(f"{what} wide range proof must have three fields")
        commitments = inner.integer_tuple(f"{what} commitments")
        pairs: dict[str, list[tuple[int, int]]] = {}
        for field_name in ("challenges", "responses"):
            pair_body = inner.frame(f"{what} {field_name}")
            pair_reader = _BundleReader(pair_body)
            pair_count = pair_reader.tuple_cardinality(f"{what} {field_name}")
            decoded_pairs: list[tuple[int, int]] = []
            for index in range(pair_count):
                item_body = pair_reader.frame(f"{what} {field_name}[{index}]")
                item_reader = _BundleReader(item_body)
                item_count = item_reader.tuple_cardinality(
                    f"{what} {field_name}[{index}]"
                )
                if item_count != 2:
                    raise ValueError(
                        f"{what} {field_name}[{index}] must be an integer pair"
                    )
                first = item_reader.int_value(f"{what} {field_name}[{index}][0]")
                second = item_reader.int_value(f"{what} {field_name}[{index}][1]")
                if not item_reader.at_end():
                    raise ValueError(
                        f"{what} {field_name}[{index}] has trailing data"
                    )
                decoded_pairs.append((first, second))
            if not pair_reader.at_end():
                raise ValueError(f"{what} {field_name} has trailing data")
            pairs[field_name] = decoded_pairs
        if not inner.at_end():
            raise ValueError(f"{what} wide range proof has trailing data")
        width = len(commitments)
        if not (
            1 <= width <= _MAX_WIDE_RANGE_BITS
            and len(pairs["challenges"]) == width
            and len(pairs["responses"]) == width
        ):
            raise ValueError(
                f"{what} wide range proof must hold 1..{_MAX_WIDE_RANGE_BITS} "
                "matching bit entries"
            )
        return WideRangeProof(
            commitments=commitments,
            challenges=tuple(pairs["challenges"]),
            responses=tuple(pairs["responses"]),
        )

    def proof(self, tag: int) -> RegionProof | RegionWideProof:
        body = self.frame("proof")
        inner = _BundleReader(body)
        count = inner.tuple_cardinality("proof")
        if count != 2:
            raise ValueError("proof must have exactly two axis sub-proofs")
        if tag == _BUNDLE_PROOF_TYPE_REGION:
            x_proof = inner.range_proof("region proof x_proof")
            y_proof = inner.range_proof("region proof y_proof")
            if not inner.at_end():
                raise ValueError("region proof has trailing data")
            return RegionProof(x_proof=x_proof, y_proof=y_proof)
        if tag == _BUNDLE_PROOF_TYPE_REGION_WIDE:
            x_proof = inner.wide_range_proof("region wide proof x_proof")
            y_proof = inner.wide_range_proof("region wide proof y_proof")
            if not inner.at_end():
                raise ValueError("region wide proof has trailing data")
            return RegionWideProof(x_proof=x_proof, y_proof=y_proof)
        raise ValueError("unknown region proof bundle proof type")


def decode_region_proof_bundle(data: bytes) -> RegionProofBundle:
    """Decode a canonical envelope back into a :class:`RegionProofBundle`.

    ``data`` must be exactly the output of
    :func:`encode_region_proof_bundle`: the magic, a known format version
    and proof-type tag, and the five fields in their fixed order with
    valid length prefixes, tuple cardinalities and integer sign bytes.
    The payload must be consumed completely with no trailing bytes. A
    truncated input, an out-of-bounds length, an unknown version or proof
    type, a non-canonical integer, an illegal region or an unexpected
    nested proof shape raises :class:`ValueError`; a non-``bytes`` input
    raises :class:`TypeError`. A decoded bundle compares equal field-for-
    field to the original and a :class:`RegionProof` payload can never be
    rebuilt as a :class:`RegionWideProof` (or vice versa).
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    reader = _BundleReader(data)
    reader.expect(_BUNDLE_MAGIC, "region proof bundle magic")
    version = reader.byte("format version")
    if version != _BUNDLE_VERSION:
        raise ValueError("unknown region proof bundle format version")
    tag = reader.byte("proof type")
    if tag not in (
        _BUNDLE_PROOF_TYPE_REGION,
        _BUNDLE_PROOF_TYPE_REGION_WIDE,
    ):
        raise ValueError("unknown region proof bundle proof type")
    x_commitment = reader.commitment("x_commitment")
    y_commitment = reader.commitment("y_commitment")
    region = reader.region()
    context = reader.frame("context")
    proof = reader.proof(tag)
    if not reader.at_end():
        raise ValueError("trailing data after region proof bundle payload")
    return RegionProofBundle(
        x_commitment=x_commitment,
        y_commitment=y_commitment,
        region=region,
        context=context,
        proof=proof,
    )


def verify_region_proof_bundle(bundle: RegionProofBundle) -> bool:
    """Verify the proof carried by a :class:`RegionProofBundle`.

    Verification follows the existing single-proof semantics exactly,
    dispatching on the ``proof`` type: :class:`RegionProof` is checked with
    :func:`verify_region` and :class:`RegionWideProof` with
    :func:`verify_region_wide`, using only the two
    :class:`PedersenCommitment` objects, the :class:`Region` and the
    ``context`` — never coordinates or blinding factors. A wrong object or
    field type (including a proof of neither region-proof type) raises
    :class:`TypeError`; every other failure — a declared range mismatch,
    a context mismatch, swapped axes or commitments, a tampered proof or a
    failed verification equation — returns ``False``. Encoding and then
    decoding a bundle preserves the verification verdict.
    """
    if not isinstance(bundle, RegionProofBundle):
        raise TypeError("bundle must be a RegionProofBundle")
    _bundle_check_commitment(bundle.x_commitment, "x_commitment")
    _bundle_check_commitment(bundle.y_commitment, "y_commitment")
    # Types only: illegal interval values are decided (False) by the
    # delegated single-proof verifiers, never raised here.
    _bundle_check_region(bundle.region, enforce_order=False)
    if not isinstance(bundle.context, bytes):
        raise TypeError("context must be bytes")
    proof = bundle.proof
    if isinstance(proof, RegionProof):
        return verify_region(
            bundle.x_commitment,
            bundle.y_commitment,
            bundle.region,
            proof,
            bundle.context,
        )
    if isinstance(proof, RegionWideProof):
        return verify_region_wide(
            bundle.x_commitment,
            bundle.y_commitment,
            bundle.region,
            proof,
            bundle.context,
        )
    raise TypeError("proof must be a RegionProof or RegionWideProof")


# ---------------------------------------------------------------------------
# Versioned binary envelopes for convex polygon membership proofs
#
# A ConvexPolygonProofBundle freezes the five public inputs of
# verify_convex_polygon (both commitments, the polygon, the external
# context and the ConvexPolygonRegionProof). Its envelope reuses the
# RegionProofBundle wire conventions verbatim:
#
#   magic (4) || version (1)
#   frame(x_commitment) || frame(y_commitment) || frame(polygon)
#   frame(context) || frame(proof)
#
# There is no proof-type tag: the payload is always one convex polygon
# proof. The polygon body is a tuple of canonical (x, y) vertex pairs;
# the proof body is a three-item tuple — the RangeProof for the x axis,
# the RangeProof for the y axis, then a tuple of one WideRangeProof per
# polygon edge in canonical boundary order.

_CONVEX_BUNDLE_MAGIC = b"zrgp"
_CONVEX_BUNDLE_VERSION = 1


@dataclass(frozen=True)
class ConvexPolygonProofBundle:
    """A versioned, canonical binary envelope for one convex polygon proof.

    Fields, in the fixed wire order: ``x_commitment`` / ``y_commitment``
    (:class:`PedersenCommitment`), ``polygon``
    (:class:`ConvexPolygonRegion`), ``context`` (``bytes``) and ``proof``
    (a :class:`ConvexPolygonRegionProof`). Bundles are positional
    construction arguments, compare by value and are immutable;
    construction performs no validation — use
    :func:`encode_convex_polygon_proof_bundle` /
    :func:`decode_convex_polygon_proof_bundle` /
    :func:`verify_convex_polygon_proof_bundle` to check.
    """

    x_commitment: PedersenCommitment
    y_commitment: PedersenCommitment
    polygon: ConvexPolygonRegion
    context: bytes
    proof: ConvexPolygonRegionProof


def _bundle_polygon(polygon: ConvexPolygonRegion) -> bytes:
    """A polygon body: a tuple of canonical ``(x, y)`` vertex pairs."""
    vertices = _normalize_polygon_vertices(polygon.vertices)
    return _bundle_tuple(
        [
            _bundle_tuple([_bundle_int(vertex[0]), _bundle_int(vertex[1])])
            for vertex in vertices
        ]
    )


def _bundle_polygon_proof_body(proof: ConvexPolygonRegionProof) -> bytes:
    """The convex polygon proof body: x/y range proofs then edge wide proofs."""
    return _bundle_tuple(
        [
            _bundle_range_proof(proof.x_proof),
            _bundle_range_proof(proof.y_proof),
            _bundle_tuple(
                [
                    _bundle_wide_range_proof(edge_proof)
                    for edge_proof in proof.edge_proofs
                ]
            ),
        ]
    )


def _bundle_check_polygon(polygon: object) -> None:
    """Type-check a polygon and re-run canonicalization for value validity.

    Wrong object or vertex element types raise :class:`TypeError`; a
    forged polygon whose vertices fail the constructor rules raises
    :class:`ValueError`.
    """
    if not isinstance(polygon, ConvexPolygonRegion):
        raise TypeError("polygon must be a ConvexPolygonRegion")
    # Re-runs every constructor rule (types, count, convexity, simplicity)
    # and yields the canonical sequence; the encoded bytes always carry
    # canonical vertices even for an object forged bypassing __post_init__.
    _normalize_polygon_vertices(polygon.vertices)


def _bundle_check_polygon_proof(proof: object) -> None:
    """Validate the nested types of a :class:`ConvexPolygonRegionProof`."""
    if not isinstance(proof, ConvexPolygonRegionProof):
        raise TypeError("proof must be a ConvexPolygonRegionProof")
    _bundle_check_range_proof(proof.x_proof, "proof x_proof")
    _bundle_check_range_proof(proof.y_proof, "proof y_proof")
    if not isinstance(proof.edge_proofs, tuple):
        raise TypeError("proof edge_proofs must be a tuple of WideRangeProof")
    for position, edge_proof in enumerate(proof.edge_proofs):
        _bundle_check_wide_range_proof(
            edge_proof, f"proof edge_proofs[{position}]"
        )


def encode_convex_polygon_proof_bundle(
    bundle: ConvexPolygonProofBundle,
) -> bytes:
    """Encode a :class:`ConvexPolygonProofBundle` into its canonical envelope.

    The output starts with the four-byte magic ``b"zrgp"`` and a one-byte
    format version, followed by the five fields in fixed order
    (``x_commitment``, ``y_commitment``, ``polygon``, ``context`` and
    ``proof``); each item is length-prefixed with a four-byte big-endian
    header and every structured body carries an explicit tuple
    cardinality, exactly as in :func:`encode_region_proof_bundle`. The
    polygon is written through its canonical vertex sequence, and the
    proof body holds the two bounding-box :class:`RangeProof` objects
    (x then y) followed by one :class:`WideRangeProof` per polygon edge
    in canonical boundary order. The same bundle object always encodes to
    the same byte string; distinct fields, contexts or sub-proofs always
    produce distinct bytes. The function returns ``bytes`` only and never
    writes to the file system or a database.

    A wrong object or field type (including a ``bool`` integer, a
    non-tuple proof field or a wide-proof pair that is not a two-tuple)
    raises :class:`TypeError`. A forged polygon whose vertices fail the
    :class:`ConvexPolygonRegion` constructor rules raises
    :class:`ValueError`.
    """
    if not isinstance(bundle, ConvexPolygonProofBundle):
        raise TypeError("bundle must be a ConvexPolygonProofBundle")
    _bundle_check_commitment(bundle.x_commitment, "x_commitment")
    _bundle_check_commitment(bundle.y_commitment, "y_commitment")
    _bundle_check_polygon(bundle.polygon)
    if not isinstance(bundle.context, bytes):
        raise TypeError("context must be bytes")
    _bundle_check_polygon_proof(bundle.proof)
    out = bytearray()
    out += _CONVEX_BUNDLE_MAGIC
    out += bytes((_CONVEX_BUNDLE_VERSION,))
    out += _bundle_frame(_bundle_commitment(bundle.x_commitment))
    out += _bundle_frame(_bundle_commitment(bundle.y_commitment))
    out += _bundle_frame(_bundle_polygon(bundle.polygon))
    out += _bundle_frame(bundle.context)
    out += _bundle_frame(_bundle_polygon_proof_body(bundle.proof))
    return bytes(out)


class _PolygonBundleReader(_BundleReader):
    """Strict envelope reader with polygon and polygon-proof constructors."""

    def polygon(self) -> ConvexPolygonRegion:
        body = self.frame("polygon")
        inner = _PolygonBundleReader(body)
        count = inner.tuple_cardinality("polygon")
        vertices: list[tuple[int, int]] = []
        for index in range(count):
            vertex_body = inner.frame(f"polygon vertices[{index}]")
            vertex_reader = _PolygonBundleReader(vertex_body)
            vertex_count = vertex_reader.tuple_cardinality(
                f"polygon vertices[{index}]"
            )
            if vertex_count != 2:
                raise ValueError(
                    f"polygon vertices[{index}] must be an (x, y) integer pair"
                )
            x_coord = vertex_reader.int_value(f"polygon vertices[{index}] x")
            y_coord = vertex_reader.int_value(f"polygon vertices[{index}] y")
            if not vertex_reader.at_end():
                raise ValueError(f"polygon vertices[{index}] has trailing data")
            vertices.append((x_coord, y_coord))
        if not inner.at_end():
            raise ValueError("polygon tuple has trailing data")
        # The constructor enforces every polygon rule (fewer than three
        # vertices, repeats, collinear triples, concavity, self-intersection)
        # and canonicalizes rotations and reversals of one boundary.
        return ConvexPolygonRegion(tuple(vertices))

    def polygon_proof(self, edge_count: int) -> ConvexPolygonRegionProof:
        body = self.frame("proof")
        inner = _PolygonBundleReader(body)
        count = inner.tuple_cardinality("proof")
        if count != 3:
            raise ValueError(
                "convex polygon proof must have exactly three fields"
            )
        x_proof = inner.range_proof("polygon proof x_proof")
        y_proof = inner.range_proof("polygon proof y_proof")
        edge_body = inner.frame("polygon proof edge_proofs")
        edge_reader = _PolygonBundleReader(edge_body)
        declared_edges = edge_reader.tuple_cardinality("polygon proof edge_proofs")
        if declared_edges != edge_count:
            raise ValueError(
                "polygon proof edge_proofs count must equal the number of "
                "polygon edges"
            )
        edge_proofs = tuple(
            edge_reader.wide_range_proof(f"polygon proof edge_proofs[{index}]")
            for index in range(declared_edges)
        )
        if not edge_reader.at_end():
            raise ValueError("polygon proof edge_proofs has trailing data")
        if not inner.at_end():
            raise ValueError("polygon proof has trailing data")
        return ConvexPolygonRegionProof(
            x_proof=x_proof,
            y_proof=y_proof,
            edge_proofs=edge_proofs,
        )


def decode_convex_polygon_proof_bundle(
    data: bytes,
) -> ConvexPolygonProofBundle:
    """Decode a canonical envelope back into a :class:`ConvexPolygonProofBundle`.

    ``data`` must be exactly the output of
    :func:`encode_convex_polygon_proof_bundle`: the magic ``b"zrgp"``, a
    known format version and the five fields in their fixed order with
    valid length prefixes, tuple cardinalities and integer sign bytes.
    The polygon vertices are rebuilt through the
    :class:`ConvexPolygonRegion` constructor, so rotations and reversals
    of one boundary decode to the same canonical region; an illegal
    polygon (too few vertices, repeats, collinear triples, concavity or
    self-intersection) is rejected. The payload must be consumed
    completely with no trailing bytes and the proof must carry exactly
    one edge :class:`WideRangeProof` per polygon edge in boundary order.
    A truncated input, an out-of-bounds length, an unknown version, a
    non-canonical integer, illegal commitment field values, an illegal
    polygon, a mismatched sub-proof shape or trailing bytes raises
    :class:`ValueError`; a non-``bytes`` input raises :class:`TypeError`.
    A decoded bundle compares equal field-for-field to the original.
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    reader = _PolygonBundleReader(data)
    reader.expect(_CONVEX_BUNDLE_MAGIC, "convex polygon proof bundle magic")
    version = reader.byte("format version")
    if version != _CONVEX_BUNDLE_VERSION:
        raise ValueError("unknown convex polygon proof bundle format version")
    x_commitment = reader.commitment("x_commitment")
    y_commitment = reader.commitment("y_commitment")
    polygon = reader.polygon()
    context = reader.frame("context")
    proof = reader.polygon_proof(len(polygon.vertices))
    if not reader.at_end():
        raise ValueError("trailing data after convex polygon proof bundle payload")
    return ConvexPolygonProofBundle(
        x_commitment=x_commitment,
        y_commitment=y_commitment,
        polygon=polygon,
        context=context,
        proof=proof,
    )


def verify_convex_polygon_proof_bundle(bundle: ConvexPolygonProofBundle) -> bool:
    """Verify the proof carried by a :class:`ConvexPolygonProofBundle`.

    Verification follows :func:`verify_convex_polygon` exactly, using only
    the two :class:`PedersenCommitment` objects, the
    :class:`ConvexPolygonRegion`, the :class:`ConvexPolygonRegionProof`
    and the ``context`` — never coordinates or blinding factors. Every
    nested type is checked across the *whole* envelope first (including a
    ``bool`` integer, a non-tuple proof field or a non-``bytes``
    context), so a proof-field type error raises :class:`TypeError` even
    when the envelope also carries a forged, geometrically invalid
    polygon — illegal geometry must never mask a wrong type. Every other
    failure — an illegal polygon shape with well-typed vertices,
    mismatched group parameters or declared ranges, a context mismatch,
    swapped commitments or axes, a different polygon, a tampered edge

    level = [_leaf_digest(leaf) for leaf in items]
    siblings: list[bytes] = []
    known = positions
    while len(level) > 1:
        size = len(level)
        known_set = set(known)
        for position in known:  # ascending: siblings collected left to right
            sibling = position ^ 1
            if sibling in known_set:
                continue  # sibling is proven too, nothing to collect
            if position == size - 1 and size % 2 == 1:
                continue  # odd last node duplicates itself
            siblings.append(level[sibling])
        if size % 2 == 1:
            level = level + [level[-1]]
        level = [
            _node_digest(level[offset], level[offset + 1])
            for offset in range(0, len(level), 2)
        ]
        known = sorted({position // 2 for position in known})
    return MerkleMultiProof(
        leaf_count=len(items),
        indices=tuple(positions),
        siblings=tuple(siblings),
    )


def verify_multi_inclusion(
    entries: Sequence[tuple[int, bytes]],
    proof: MerkleMultiProof,
    root: bytes,
) -> bool:
    """Check ``entries`` against ``proof`` and Merkle ``root`` without the full leaf set.

    ``entries`` holds one ``(index, leaf)`` pair per entry, in the exact order
    of ``proof.indices``. Type errors raise :class:`TypeError`; empty,
    misordered, out-of-range, miscounted or tampered inputs return False.
    """
    _check_bytes(root, "root")
    if not isinstance(proof, MerkleMultiProof):
        raise TypeError("proof must be a MerkleMultiProof")
    if not isinstance(proof.leaf_count, int) or isinstance(proof.leaf_count, bool):
        raise TypeError("proof leaf_count must be an integer")
    if not isinstance(proof.indices, tuple):
        raise TypeError("proof indices must be a tuple of integers")
    for index in proof.indices:
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError("proof indices must be a tuple of integers")
    if not isinstance(proof.siblings, tuple):
        raise TypeError("proof siblings must be a tuple of bytes")
    for sibling in proof.siblings:
        _check_bytes(sibling, "proof sibling")
    if isinstance(entries, (bytes, bytearray, str)) or not isinstance(entries, Sequence):
        raise TypeError("entries must be a sequence of (index, leaf) pairs")
    pairs: list[tuple[int, bytes]] = []
    for position, entry in enumerate(entries):
        if not isinstance(entry, (tuple, list)) or len(entry) != 2:
            raise TypeError(f"entries[{position}] must be an (index, leaf) pair")
        index, leaf = entry
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"entries[{position}] index must be an integer")
        if not isinstance(leaf, bytes):
            raise TypeError(f"entries[{position}] leaf must be bytes")
        pairs.append((index, leaf))
    if proof.leaf_count < 1:
        return False
    if not proof.indices:
        return False
    if any(
        later <= earlier for earlier, later in zip(proof.indices, proof.indices[1:])
    ):
        return False  # duplicates or out-of-order indices
    if proof.indices[0] < 0 or proof.indices[-1] >= proof.leaf_count:
        return False
    if not pairs:
        return False
    if tuple(index for index, _ in pairs) != proof.indices:
        return False
    if len(root) != _MERKLE_DIGEST_SIZE:
        return False
    if any(len(sibling) != _MERKLE_DIGEST_SIZE for sibling in proof.siblings):
        return False
    known = {index: _leaf_digest(leaf) for index, leaf in pairs}
    size = proof.leaf_count
    siblings = proof.siblings
    cursor = 0
    while size > 1:
        next_known: dict[int, bytes] = {}
        for position in sorted(known):
            sibling = position ^ 1
            if sibling in known:
                sibling_digest = known[sibling]
            elif position == size - 1 and size % 2 == 1:
                sibling_digest = known[position]  # odd last node duplicates itself
            else:
                if cursor >= len(siblings):
                    return False  # proof ran out of siblings
                sibling_digest = siblings[cursor]
                cursor += 1
            if position % 2 == 0:
                digest = _node_digest(known[position], sibling_digest)
            else:
                digest = _node_digest(sibling_digest, known[position])
            next_known[position // 2] = digest
        known = next_known
        size = (size + 1) // 2
    if cursor != len(siblings):
        return False  # every sibling must be consumed
    return hmac.compare_digest(known[0], root)


# ---------------------------------------------------------------------------
# Canonical transport envelope for Merkle multi-inclusion proofs
#
# A MerkleMultiProofBundle freezes the three arguments of
# verify_multi_inclusion (root, proof, entries) into one immutable object
# that can be encoded into a self-contained byte string, shipped across
# processes and verified again after decoding. The wire format reuses the
# region-proof-envelope primitives (four-byte big-endian length frames,
# sign-byte-plus-shortest-magnitude integers, tuples with an explicit
# cardinality) under its own magic and format version, so a multi-proof
# envelope can never be mistaken for a region proof envelope. Encoding is
# a pure function of the field values: the same bundle always maps to the
# same bytes, and decoding those bytes rebuilds an equal bundle.

_MERKLE_MULTI_BUNDLE_MAGIC = b"zmmp"
_MERKLE_MULTI_BUNDLE_VERSION = 1


@dataclass(frozen=True)
class MerkleMultiProofBundle:
    """A versioned, canonical binary envelope for one multi-inclusion proof.

    Fields, in the fixed wire order: ``root`` (``bytes``), ``proof``
    (:class:`MerkleMultiProof`) and ``entries``
    (``tuple[tuple[int, bytes], ...]`` of ``(index, leaf)`` pairs in the
    exact order of ``proof.indices``). Bundles are positional construction
    arguments, compare by value and are immutable; construction performs no
    validation — use :func:`encode_merkle_multi_proof_bundle` /
    :func:`verify_merkle_multi_proof_bundle` to check.
    """

    root: bytes
    proof: MerkleMultiProof
    entries: tuple[tuple[int, bytes], ...]


def _check_merkle_multi_bundle_proof_types(proof: object) -> None:
    """Type-check a bundle ``proof`` field (values are decided elsewhere)."""
    if not isinstance(proof, MerkleMultiProof):
        raise TypeError("proof must be a MerkleMultiProof")
    if not isinstance(proof.leaf_count, int) or isinstance(proof.leaf_count, bool):
        raise TypeError("proof leaf_count must be an integer")
    if not isinstance(proof.indices, tuple):
        raise TypeError("proof indices must be a tuple of integers")
    for index in proof.indices:
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError("proof indices must be a tuple of integers")
    if not isinstance(proof.siblings, tuple):
        raise TypeError("proof siblings must be a tuple of bytes")
    for sibling in proof.siblings:
        _check_bytes(sibling, "proof sibling")


def _check_merkle_multi_bundle_entries_types(entries: object) -> None:
    """Type-check a bundle ``entries`` field (values are decided elsewhere)."""
    if not isinstance(entries, tuple):
        raise TypeError("entries must be a tuple of (index, leaf) pairs")
    for position, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError(f"entries[{position}] must be an (index, leaf) pair")
        index, leaf = entry
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"entries[{position}] index must be an integer")
        if not isinstance(leaf, bytes):
            raise TypeError(f"entries[{position}] leaf must be bytes")


def encode_merkle_multi_proof_bundle(bundle: MerkleMultiProofBundle) -> bytes:
    """Encode a :class:`MerkleMultiProofBundle` into its canonical byte envelope.

    The same bundle object always encodes to the same byte string. The
    output starts with the four-byte magic ``b"zmmp"`` and a one-byte
    format version, followed by the three fields in fixed order
    (``root``, ``proof``, ``entries``); each item is length-prefixed with
    a four-byte big-endian header. The proof body is the three-item tuple
    ``(leaf_count, indices, siblings)`` and each entry the two-item tuple
    ``(index, leaf)``; integers (including out-of-range or negative
    values) carry a sign byte and a shortest big-endian magnitude, tuples
    carry an explicit cardinality and ``bytes`` items are framed raw. The
    function returns ``bytes`` only and never writes to the file system or
    a database.

    Only types are checked: a wrong object or field type (including a
    ``bool`` integer, a non-tuple ``indices``/``siblings``/``entries``
    field or an entry that is not an ``(index, leaf)`` pair) raises
    :class:`TypeError`. A bundle whose proof is semantically inconsistent
    (misordered or duplicate indices, an entries/indices mismatch, an
    out-of-range index, a non-positive ``leaf_count``) still encodes to
    ``bytes``; those cases are decided by
    :func:`verify_merkle_multi_proof_bundle`.
    """
    if not isinstance(bundle, MerkleMultiProofBundle):
        raise TypeError("bundle must be a MerkleMultiProofBundle")
    if not isinstance(bundle.root, bytes):
        raise TypeError("root must be bytes")
    _check_merkle_multi_bundle_proof_types(bundle.proof)
    _check_merkle_multi_bundle_entries_types(bundle.entries)
    proof = bundle.proof
    proof_body = _bundle_tuple(
        [
            _bundle_int(proof.leaf_count),
            _bundle_tuple([_bundle_int(index) for index in proof.indices]),
            _bundle_tuple(list(proof.siblings)),
        ]
    )
    entries_body = _bundle_tuple(
        [
            _bundle_tuple([_bundle_int(index), leaf])
            for index, leaf in bundle.entries
        ]
    )
    out = bytearray()
    out += _MERKLE_MULTI_BUNDLE_MAGIC
    out += bytes((_MERKLE_MULTI_BUNDLE_VERSION,))
    out += _bundle_frame(bundle.root)
    out += _bundle_frame(proof_body)
    out += _bundle_frame(entries_body)
    return bytes(out)


def _read_merkle_multi_bundle_proof(reader: _BundleReader) -> MerkleMultiProof:
    """Read the framed proof body: ``(leaf_count, indices, siblings)``."""
    body = reader.frame("proof")
    inner = _BundleReader(body)
    count = inner.tuple_cardinality("proof")
    if count != 3:
        raise ValueError("proof must have exactly three fields")
    leaf_count = inner.int_value("proof leaf_count")
    indices_body = inner.frame("proof indices")
    indices_reader = _BundleReader(indices_body)
    index_count = indices_reader.tuple_cardinality("proof indices")
    indices = tuple(
        indices_reader.int_value(f"proof indices[{position}]")
        for position in range(index_count)
    )
    if not indices_reader.at_end():
        raise ValueError("proof indices tuple has trailing data")
    siblings_body = inner.frame("proof siblings")
    siblings_reader = _BundleReader(siblings_body)
    sibling_count = siblings_reader.tuple_cardinality("proof siblings")
    siblings = tuple(
        siblings_reader.frame(f"proof siblings[{position}]")
        for position in range(sibling_count)
    )
    if not siblings_reader.at_end():
        raise ValueError("proof siblings tuple has trailing data")
    if not inner.at_end():
        raise ValueError("proof has trailing data")
    return MerkleMultiProof(
        leaf_count=leaf_count, indices=indices, siblings=siblings
    )


def _read_merkle_multi_bundle_entries(
    reader: _BundleReader,
) -> tuple[tuple[int, bytes], ...]:
    """Read the framed entries body: a tuple of ``(index, leaf)`` pairs."""
    body = reader.frame("entries")
    inner = _BundleReader(body)
    count = inner.tuple_cardinality("entries")
    entries: list[tuple[int, bytes]] = []
    for position in range(count):
        entry_body = inner.frame(f"entries[{position}]")
        entry_reader = _BundleReader(entry_body)
        entry_count = entry_reader.tuple_cardinality(f"entries[{position}]")
        if entry_count != 2:
            raise ValueError(f"entries[{position}] must be an (index, leaf) pair")
        index = entry_reader.int_value(f"entries[{position}] index")
        leaf = entry_reader.frame(f"entries[{position}] leaf")
        if not entry_reader.at_end():
            raise ValueError(f"entries[{position}] has trailing data")
        entries.append((index, leaf))
    if not inner.at_end():
        raise ValueError("entries tuple has trailing data")
    return tuple(entries)


def decode_merkle_multi_proof_bundle(data: bytes) -> MerkleMultiProofBundle:
    """Decode a canonical envelope back into a :class:`MerkleMultiProofBundle`.

    ``data`` must be exactly the output of
    :func:`encode_merkle_multi_proof_bundle`: the magic, a known format
    version, and the three fields in their fixed order with valid length
    prefixes, tuple cardinalities and canonical integers. The payload must
    be consumed completely with no trailing bytes. A truncated input, an
    out-of-bounds length, an unknown version, a non-canonical integer, a
    malformed tuple shape or trailing bytes raises :class:`ValueError`; a
    non-``bytes`` input raises :class:`TypeError`. Decoding checks the
    encoding only: a representable bundle whose proof does not verify
    still decodes successfully, and the decoded bundle compares equal
    field-for-field to the original.
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    reader = _BundleReader(data)
    reader.expect(_MERKLE_MULTI_BUNDLE_MAGIC, "merkle multi proof bundle magic")
    version = reader.byte("format version")
    if version != _MERKLE_MULTI_BUNDLE_VERSION:
        raise ValueError("unknown merkle multi proof bundle format version")
    root = reader.frame("root")
    proof = _read_merkle_multi_bundle_proof(reader)
    entries = _read_merkle_multi_bundle_entries(reader)
    if not reader.at_end():
        raise ValueError("trailing data after merkle multi proof bundle payload")
    return MerkleMultiProofBundle(root=root, proof=proof, entries=entries)


def verify_merkle_multi_proof_bundle(bundle: MerkleMultiProofBundle) -> bool:
    """Verify the proof carried by a :class:`MerkleMultiProofBundle`.

    Verification reuses the existing multi-inclusion semantics exactly:
    the bundle's ``entries``, ``proof`` and ``root`` are handed to
    :func:`verify_multi_inclusion`, which checks the root and digest
    sizes, the strictly increasing duplicate-free ``proof.indices``
    against ``proof.leaf_count``, the exact entries/indices
    correspondence and the sibling consumption. A wrong object or field
    type (including a ``bool`` integer or a non-tuple field) raises
    :class:`TypeError`; every semantic inconsistency — a tampered leaf or
    root, duplicate or misordered indices, an out-of-range index, a
    miscounted entries list, a spliced or truncated sibling sequence —
    returns ``False``. Encoding and then decoding a bundle preserves the
    verification verdict.
    """
    if not isinstance(bundle, MerkleMultiProofBundle):
        raise TypeError("bundle must be a MerkleMultiProofBundle")
    if not isinstance(bundle.root, bytes):
        raise TypeError("root must be bytes")
    _check_merkle_multi_bundle_proof_types(bundle.proof)
    _check_merkle_multi_bundle_entries_types(bundle.entries)
    return verify_multi_inclusion(bundle.entries, bundle.proof, bundle.root)


@dataclass(frozen=True)
class MerkleMultiBatchEntry:
    """One independent item of a multi-inclusion batch verification.

    Fields, in order: ``entries`` (``tuple[tuple[int, bytes], ...]`` of
    ``(index, leaf)`` pairs in the exact order of ``proof.indices``),
    ``proof`` (:class:`MerkleMultiProof`) and ``root`` (``bytes``) —
    exactly the arguments of :func:`verify_multi_inclusion`, in the same
    order. All three are positional construction arguments; entries
    compare by value and are immutable.
    """

    entries: tuple[tuple[int, bytes], ...]
    proof: MerkleMultiProof
    root: bytes


def _check_multi_inclusion_batch_entries_types(
    batch: object,
) -> list[MerkleMultiBatchEntry]:
    """Validate the multi-inclusion-batch ``batch`` argument types.

    Mirrors the type checks of :func:`verify_multi_inclusion` for *every*
    item before any verification runs: ``batch`` must be a non-``bytes`` /
    ``bytearray`` / ``str`` sequence of :class:`MerkleMultiBatchEntry`
    objects whose ``entries`` is a tuple of two-item ``(index, leaf)``
    pairs with a non-``bool`` integer index and ``bytes`` leaf, whose
    ``root`` is ``bytes`` and whose ``proof`` is a
    :class:`MerkleMultiProof` with a non-``bool`` integer
    ``leaf_count``, a tuple of non-``bool`` integer ``indices`` and a
    tuple-of-bytes ``siblings``. The whole batch is walked (a bad type
    in a later item still raises), and the items are copied into a fresh
    list so the inputs are never mutated. An empty batch is left to
    :func:`verify_multi_inclusion_batch` to reject with ``False``;
    structural/value problems (a non-positive ``leaf_count``, empty or
    out-of-order indices, malformed digest lengths, an index out of
    range, mismatched pair/indices counts) are left to
    :func:`verify_multi_inclusion` during verification.
    """
    if isinstance(batch, (bytes, bytearray, str)) or not isinstance(batch, Sequence):
        raise TypeError("batch must be a sequence of MerkleMultiBatchEntry")
    items: list[MerkleMultiBatchEntry] = []
    for position, item in enumerate(batch):
        if not isinstance(item, MerkleMultiBatchEntry):
            raise TypeError(
                f"batch[{position}] must be a MerkleMultiBatchEntry"
            )
        if not isinstance(item.entries, tuple):
            raise TypeError(
                f"batch[{position}] entries must be a tuple of (index, leaf) pairs"
            )
        for pair_position, pair in enumerate(item.entries):
            if not isinstance(pair, tuple) or len(pair) != 2:
                raise TypeError(
                    f"batch[{position}] entries[{pair_position}] must be an "
                    "(index, leaf) pair"
                )
            index, leaf = pair
            if not isinstance(index, int) or isinstance(index, bool):
                raise TypeError(
                    f"batch[{position}] entries[{pair_position}] index must be "
                    "an integer"
                )
            if not isinstance(leaf, bytes):
                raise TypeError(
                    f"batch[{position}] entries[{pair_position}] leaf must be bytes"
                )
        _check_bytes(item.root, f"batch[{position}] root")
        proof = item.proof
        if not isinstance(proof, MerkleMultiProof):
            raise TypeError(
                f"batch[{position}] proof must be a MerkleMultiProof"
            )
        if not isinstance(proof.leaf_count, int) or isinstance(proof.leaf_count, bool):
            raise TypeError(
                f"batch[{position}] proof leaf_count must be an integer"
            )
        if not isinstance(proof.indices, tuple):
            raise TypeError(
